
ALTER TABLE public.articles
  ADD COLUMN resources JSONB NOT NULL DEFAULT '[]'::jsonb;

INSERT INTO public.articles (category_id, slug, title, summary, body, reading_minutes, is_required, position, external_url, external_label, is_tool, resources)
SELECT c.id,
  'chattigo-manual-de-uso',
  'Manual completo de uso de Chattigo (capacitación oficial)',
  'La academia oficial de Chattigo más el recorrido de los cinco módulos que todo agente debe dominar.',
  '## Capacitación oficial\nChattigo tiene su propia academia de capacitación en línea. Ahí están los cursos, videos y evaluaciones oficiales de la plataforma. Usa el botón de acceso para entrar con las credenciales que te asigne tu responsable.\n\nRecorre los módulos en orden durante tu primera semana de atención y vuelve a la academia cada vez que se libere una función nueva.\n\n## Módulo 1 · Ingreso a la plataforma\n- Acceso, recuperación de contraseña y buenas prácticas de credenciales.\n- Reconocer la pantalla principal: bandeja, panel de estado y datos del contacto.\n- Estados del agente: **Disponible**, en pausa y desconectado. Si no estás disponible, no se te asignan conversaciones.\n- Cierre de sesión correcto al terminar el turno para que tus casos se reasignen.\n\n## Módulo 2 · Gestión de chats entrantes y conversaciones omnicanal\n- Cómo se asignan las conversaciones y qué significa cada estado.\n- Atender WhatsApp, web y redes desde la misma bandeja sin cambiar de herramienta.\n- Validar identidad del cliente antes de dar cualquier información del caso.\n- Ver el historial del contacto para no repetir preguntas ni ofrecimientos.\n- Transferir a otro agente o área cuando el caso no es tuyo, siempre con un resumen escrito.\n\n## Módulo 3 · Etiquetado y categorización de tickets\n- Qué es una etiqueta y por qué define los reportes de gestión.\n- Elegir el motivo real de contacto, no el más cómodo.\n- Etiquetas obligatorias antes de cerrar: motivo, resultado y área responsable.\n- Errores frecuentes: cerrar sin etiqueta, usar “otros” por defecto, mezclar dos motivos en una misma conversación.\n\n## Módulo 4 · Respuestas rápidas (canned responses)\n- Dónde se encuentran las respuestas predefinidas y cómo insertarlas.\n- Personalizar el saludo y el nombre; **nunca** modificar condiciones, importes ni plazos.\n- Cuándo no usar una respuesta rápida: reclamos, temas sensibles y casos legales se escriben a mano.\n- Proponer una respuesta rápida nueva: se solicita a tu supervisor con el texto sugerido.\n\n## Módulo 5 · Cierre y escalamiento de interacciones\n- Cerrar correctamente: resolución confirmada, etiquetas cargadas y próximo paso comunicado.\n- Registrar en Abogados Nx y en Gestión de Mora cualquier compromiso asumido.\n- Cuándo escalar: cliente molesto, pedido fuera de tu alcance, tema legal o error nuestro.\n- Cómo escalar: transferencia al área correspondiente con resumen, más aviso a tu supervisor si hay riesgo.\n- Conversaciones sin respuesta del cliente: cierre por inactividad con la etiqueta correspondiente, nunca en blanco.\n\n## Cómo aprovechar la academia\n1. Haz un módulo por día durante la primera semana.\n2. Practica en paralelo con la plataforma abierta.\n3. Anota tus dudas y llévalas a tu 1:1 con el supervisor.\n4. Repite el módulo de etiquetado antes de tu primer cierre de mes: es lo que más impacta en los reportes.\n\n## Solución de problemas de la capacitación\n- **No puedo ingresar a la academia**: solicita el alta a tu responsable; el usuario de la academia no es el mismo de la plataforma.\n- **El video no carga**: prueba otro navegador y desactiva bloqueadores.\n- **Perdí mi avance**: el progreso se guarda por usuario; verifica que no estés usando un acceso compartido.',
  6, true, 12,
  'https://chattigo.sabionet.com/',
  'Abrir la academia de Chattigo',
  true,
  '[{"label":"Academia de capacitación Chattigo","url":"https://chattigo.sabionet.com/","description":"Cursos oficiales, videos y evaluaciones de la plataforma."},{"label":"Ingresar a Chattigo","url":"https://login.chattigo.com","description":"La plataforma de trabajo diaria para practicar lo aprendido."}]'::jsonb
FROM public.categories c WHERE c.slug = 'herramientas-clave';

UPDATE public.articles
SET title = 'Tablas dinámicas de Excel y plantillas operativas',
    summary = 'Las planillas y reportes analíticos de gestión de casos, con acceso directo a la carpeta y a cada archivo de trabajo.',
    external_url = 'https://drive.google.com/drive/folders/1d57ujbWhPLcqPNcQQb-mr-LGNaJ_ykjh?usp=drive_link',
    external_label = 'Abrir carpeta de tablas y plantillas',
    resources = '[
      {"label":"Carpeta general de tablas y plantillas","url":"https://drive.google.com/drive/folders/1d57ujbWhPLcqPNcQQb-mr-LGNaJ_ykjh?usp=drive_link","description":"Todas las plantillas y reportes operativos en un solo lugar. Empieza siempre por acá."},
      {"label":"Planilla operativa 1","url":"https://docs.google.com/spreadsheets/d/1fGbagC7wW72htdVCtQS_AJiDjGa4jxbI/edit?usp=drive_link","description":"Planilla de gestión de casos: base de trabajo diaria con sus tablas dinámicas."},
      {"label":"Archivo de trabajo 2","url":"https://drive.google.com/file/d/1dZkdCyo5KONbOcMgXvYshP9fyfdL9vw5/view?usp=drive_link","description":"Reporte de apoyo para el seguimiento de cartera. Abrir o descargar para trabajar en Excel."},
      {"label":"Archivo de trabajo 3","url":"https://drive.google.com/file/d/1rRdhBP-QH20NXfxrJsqNdziE38MKwUJP/view?usp=drive_link","description":"Reporte complementario de análisis de gestión. Abrir o descargar para trabajar en Excel."}
    ]'::jsonb,
    body = '## Para qué sirven\nSon los reportes en Excel que resumen la cartera y la gestión: casos por tramo, resultados por gestor, promesas cumplidas y recupero del período. Todas las plantillas viven en la carpeta compartida de Drive; los archivos individuales están enlazados arriba para abrirlos o descargarlos directamente.\n\n## Antes de empezar\n- Trabaja siempre sobre **una copia** de la plantilla, nunca sobre el original de la carpeta.\n- Nombra tu copia con el período y tu área, por ejemplo `Gestion_Cartera_2026-09_Cobranzas`.\n- Si un archivo pide permiso de acceso, solicítalo a tu responsable; no lo dupliques por fuera de la carpeta.\n\n## Paso a paso\n1. Abre la carpeta general y ubica la plantilla del período.\n2. Descarga la planilla operativa o el archivo de trabajo que necesites (Archivo → Descargar → Excel si lo abres en Drive).\n3. Exporta la base desde Gestión de Mora o desde el Drive de Carga de Transferencias.\n4. Pega los datos en la pestaña *Datos*, sin filas vacías ni títulos intermedios.\n5. Verifica formatos: fechas como fecha, importes como número.\n6. Ve a la pestaña del reporte y usa **Actualizar todo** (Ctrl + Alt + F5).\n7. Revisa que no aparezcan filas “(en blanco)”: significan datos sucios en el origen.\n8. Guarda tu copia en la carpeta del período y comparte el enlace, no el archivo adjunto.\n\n## Cómo reflejar los datos en Gestión de Mora\nEl Excel analiza; **Gestión de Mora es la fuente de verdad**. El circuito correcto es:\n\n1. Trabaja tu priorización en la planilla (tramo, saldo, probabilidad de recupero).\n2. Cada contacto o resultado que surja de ese análisis se carga en Gestión de Mora, caso por caso: motivo, resultado y fecha de próximo contacto.\n3. Las promesas de pago se cargan en Gestión de Mora con fecha e importe; la planilla no genera seguimiento por sí sola.\n4. Los pagos informados se registran además en el Drive de Carga de Transferencias.\n5. Al cierre, vuelve a exportar de Gestión de Mora y actualiza el reporte: los totales del Excel deben coincidir con el sistema.\n\nSi el Excel y Gestión de Mora no coinciden, gana el sistema: revisa qué gestión quedó sin cargar.\n\n## Consejos según tu rol\n- **Gestores**: usa el reporte para priorizar el tramo con mayor probabilidad de recupero, y carga en Gestión de Mora lo que gestiones.\n- **Supervisión**: compara semana contra semana, no día contra día; el ruido diario engaña.\n- **Administración**: cuadra el total del reporte contra la planilla de transferencias antes de informar.\n\n## Solución de problemas\n- **La tabla no toma las filas nuevas**: el rango de origen quedó corto; amplía el rango o convierte el origen en tabla y actualiza.\n- **Aparecen duplicados**: revisa espacios al final del documento o del número de caso.\n- **Suma de importes en cero**: la columna quedó como texto; conviértela a número y actualiza.\n- **“Solo lectura” al abrir desde Drive**: descarga el archivo o pide permiso de edición; no trabajes en una copia local sin subirla después.\n- **Archivo muy pesado o lento**: elimina columnas que no usas y evita formatos condicionales sobre columnas completas.',
    reading_minutes = 6,
    is_required = true
WHERE slug = 'tablas-dinamicas-excel';
